    imageUrl: 'https://www.lostiempos.com/sites/default/files/media_imagen/2026/5/18/4_p_1_lopezzzzzzzzzzz.jpg',
    imageCaption: 'Reporteros durante cobertura de conflictos en Bolivia. Foto: Carlos López / Los Tiempos',
    categoryEs: 'Mundo',
